        d = 2
        while d * d <= x:
            while x % d == 0:
                fs[d] = fs.get(d, 0) + 1
                x //= d
            d += 1
        if x > 1:
            fs[x] = fs.get(x, 0) + 1
        factors.append(fs)

    primes = set()
    for fs in factors:
        primes.update(fs)

    answer = 1
    for p in primes:
        steps = [fs.get(p, 0) for fs in factors]
        limit = sum(steps)
        weights = [pow(p, h, MOD) for h in range(limit + 1)]

        # seen[h]: paths at height h that have visited height 0
        # unseen[h]: paths at height h that have not visited height 0
        seen = [0] * (limit + 1)
        unseen = [0] * (limit + 1)
        seen[0] = 1
        for h in range(1, limit + 1):
            unseen[h] = weights[h]

        for step in steps:
            next_seen = [0] * (limit + 1)
            next_unseen = [0] * (limit + 1)
            for h in range(limit + 1):
                v_seen = seen[h]
                v_unseen = unseen[h]
                if not v_seen and not v_unseen:
                    continue
                if step == 0:
                    destinations = (h,)
                else:
                    destinations = (h - step, h + step)
                for nh in destinations:
                    if nh < 0 or nh > limit:
                        continue
                    w = weights[nh]
                    if nh == 0:
                        next_seen[0] = (next_seen[0] + (v_seen + v_unseen) * w) % MOD
                    else:
                        next_seen[nh] = (next_seen[nh] + v_seen * w) % MOD
                        next_unseen[nh] = (next_unseen[nh] + v_unseen * w) % MOD
            seen, unseen = next_seen, next_unseen

        prime_sum = sum(seen) % MOD
        answer = answer * prime_sum % MOD

    print(answer)

