from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, i))

        top1 = top2 = 0
        top_count = 0
        top_id = -1
        gains = [0] * m
        total = 0

        for right in range(1, n + 1):
            for a, pair_id in buckets[right]:
                if a > top1:
                    top2 = top1
                    top1 = a
                    top_count = 1
                    top_id = pair_id
                elif a == top1:
                    top_count += 1
                elif a > top2:
                    top2 = a

            # The valid starts for subarrays ending here are top1 + 1..right.
            total += right - top1
            # Removing the unique maximum constraint lowers the boundary to top2.
            if top_count == 1:
                gains[top_id] += top1 - top2

        return total + max(gains)

