import sys
import math


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, budget = data[0], data[1]
    processes = []
    for i in range(n):
        a, p, b, q = data[2 + 4 * i: 6 + 4 * i]
        processes.append((a, p, b, q, math.gcd(a, b)))

    def feasible(target):
        total_cost = 0
        for a, p, b, q, g in processes:
            if p * b <= q * a:  # S has no greater cost per unit capacity
                best = 10**30
                for y in range(a // g):
                    remaining = target - b * y
                    x = (remaining + a - 1) // a if remaining > 0 else 0
                    best = min(best, x * p + y * q)
            else:
                best = 10**30
                for x in range(b // g):
                    remaining = target - a * x
                    y = (remaining + b - 1) // b if remaining > 0 else 0
                    best = min(best, x * p + y * q)
            total_cost += best
            if total_cost > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)


if __name__ == '__main__':
    main()

