from math import comb

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)
        counts = [0] * (n + 1)

        # Count values smaller than s, grouped by their number of set bits.
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for suffix_ones in range(remaining + 1):
                    counts[prefix_ones + suffix_ones] += comb(remaining, suffix_ones)
                prefix_ones += 1

        answer = 0
        for ones in range(1, n + 1):
            # A number with this many set bits takes 1 + depth(ones) steps.
            value = ones
            depth = 0
            while value > 1:
                value = value.bit_count()
                depth += 1
            if depth < k:
                answer += counts[ones]

        return answer % (10**9 + 7)

