from math import comb
class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)
        counts = [0] * (n + 1)
        prefix = 0
        for i, bit in enumerate(s):
            if bit == '1':
                rem = n - i - 1
                for q in range(rem + 1):
                    counts[prefix + q] += comb(rem, q)
                prefix += 1
        good = [False] * (n + 1)
        for t in range(1, n + 1):
            x = t
            steps = 0
            while x > 1:
                x = x.bit_count()
                steps += 1
            good[t] = steps < k
        return sum(counts[t] for t in range(1, n + 1) if good[t]) % (10**9 + 7)

