import sys

def feasible(ps):
    if not ps:
        return True
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    # All person endpoints must have equal potential.
    for a, b, _ in ps:
        x, y = find(a), find(b)
        if x != y:
            parent[x] = y

    roots = {find(i) for i in range(n)}
    graph = {x: set() for x in roots}
    indeg = {x: 0 for x in roots}
    for a, b, sign in ps:
        u, v = find(a), find(b)
        for x in range(a + 1, b):
            z = find(x)
            # sign +: interior must be higher; sign -: interior lower.
            low, high = (u, z) if sign > 0 else (z, u)
            if low == high:
                return False
            if high not in graph[low]:
                graph[low].add(high)
                indeg[high] += 1

    stack = [x for x in roots if indeg[x] == 0]
    visited = 0
    while stack:
        u = stack.pop()
        visited += 1
        for v in graph[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                stack.append(v)
    return visited == len(roots)


