def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    H, W, X = data[:3]
    P, Q = data[3] - 1, data[4] - 1
    vals = data[5:]

    seen = bytearray(H * W)
    start = P * W + Q
    seen[start] = 1
    power = vals[start]
    heap = []

    def add_neighbors(r, c):
        if r > 0:
            v = (r - 1) * W + c
            if not seen[v]:
                seen[v] = 1
                heapq.heappush(heap, (vals[v], v))
        if r + 1 < H:
            v = (r + 1) * W + c
            if not seen[v]:
                seen[v] = 1
                heapq.heappush(heap, (vals[v], v))
        if c > 0:
            v = r * W + c - 1
            if not seen[v]:
                seen[v] = 1
                heapq.heappush(heap, (vals[v], v))
        if c + 1 < W:
            v = r * W + c + 1
            if not seen[v]:
                seen[v] = 1
                heapq.heappush(heap, (vals[v], v))

    add_neighbors(P, Q)
    while heap:
        val, idx = heap[0]
        if val * X >= power:
            break
        heapq.heappop(heap)
        power += val
        add_neighbors(idx // W, idx % W)

    print(power)

