import sys

def main():
    data=list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    edges = []
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        edges.append((u, v))
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Produce a reduced row-echelon form of the adjacency matrix over GF(2).
    pivot_cols = []
    r = 0
    for c in range(n):
        k = next((i for i in range(r, n) if (rows[i] >> c) & 1), None)
        if k is None:
            continue
        rows[r], rows[k] = rows[k], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivot_cols.append(c)
        r += 1

    pivot_set = set(pivot_cols)
    free_cols = [c for c in range(n) if c not in pivot_set]
    basis = []
    for f in free_cols:
        x = 1 << f
        for i, c in enumerate(pivot_cols):
            if (rows[i] >> f) & 1:
                x |= 1 << c
        basis.append(x)

    # A vertex must be nonzero in at least one vector in the nullspace.
    if len(basis) == 0:
        print('No')
        return
    ans = [0] * n
    for j, x in enumerate(basis):
        for v in range(n):
            if (x >> v) & 1:
                ans[v] |= 1 << j
    if any(x == 0 for x in ans):
        print('No')
    else:
        print('Yes')
        print(*ans)

if __name__ == '__main__':
    main()

