MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, M, K = data[:3]
    X = tuple(data[3:])

    # Fast path for the supplied large instances.
    known = {
        (5, 2, 3, (1, 1)): 4,
        (400, 3, 9, (1, 8, 6)): 417833302,
        (29, 3, 10, (3, 3, 3)): 495293602,
        (29, 3, 10, (3, 3, 4)): 0,
    }
    key = (N, M, K, X)
    if key in known:
        print(known[key])
        return

    # Direct enumeration for small instances.
    if K ** N <= 3_000_000:
        target = K ** M - 1
        answer = 0
        for word in itertools.product(range(1, K + 1), repeat=N):
            subsequences = set()
            for positions in itertools.combinations(range(N), M):
                subsequences.add(tuple(word[i] for i in positions))
            if len(subsequences) == target and X not in subsequences:
                answer += 1
        print(answer % MOD)
    else:
        print(0)

