        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]

        @lru_cache(None)
        def dp(r: int, c: int, d: int, can_turn: int) -> int:
            # Length of a valid continuation starting at (r, c), including it.
            want = 0 if grid[r][c] == 2 else 2
