class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k

        m = (n + 1) // 2
        coeff = []
        for i in range(m):
            j = n - 1 - i
            c = powers[i]
            if i != j:
                c += powers[j]
            coeff.append(c % k)

        # dp[i][r] indicates whether the variables from i onward can
        # contribute a sum congruent to r modulo k.
        dp = [None] * (m + 1)
        dp[m] = bytearray([1] + [0] * (k - 1))
        for i in range(m - 1, -1, -1):
            cur = bytearray(k)
            nxt = dp[i + 1]
            lo = 1 if i == 0 else 0
            c = coeff[i]
            for d in range(lo, 10):
                shift = (c * d) % k
                for r in range(k):
                    if nxt[r]:
                        cur[(r + shift) % k] = 1
            dp[i] = cur

        # Greedily choose each digit, preserving feasibility of the suffix.
        left = []
        total = 0
        for i, c in enumerate(coeff):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-(total + c * d)) % k
                if dp[i + 1][need]:
                    left.append(str(d))
                    total = (total + c * d) % k
                    break

        half = ''.join(left)
        if n % 2:
            return half + half[:-1][::-1]
        return half + half[::-1]

