from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # nxt[i] is the first index after i with a strictly greater value.
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        # Binary lifting over consecutive runs of equal prefix-maximum value.
        # A jump of level p represents 2**p complete runs; -1 marks invalid.
        log = n.bit_length()
        jump = [nxt]
        run_sum = [[nums[i] * (nxt[i] - i) for i in range(n)]]
        for _ in range(1, log):
            prev_jump = jump[-1]
            prev_sum = run_sum[-1]
            cur_jump = [-1] * n
            cur_sum = [0] * n
            for i in range(n):
                mid = prev_jump[i]
                if mid < n and prev_jump[mid] >= 0:
                    cur_jump[i] = prev_jump[mid]
                    cur_sum[i] = prev_sum[i] + prev_sum[mid]
            jump.append(cur_jump)
            run_sum.append(cur_sum)

        prefix = [0]
        for value in nums:
            prefix.append(prefix[-1] + value)

        def increments_needed(left: int, right: int) -> int:
            # Sum of prefix maxima minus the original elements.
            pos = left
            maximum_sum = 0
            for p in range(log - 1, -1, -1):
                if pos == n:
                    break
                dest = jump[p][pos]
                if dest >= 0 and dest <= right + 1:
                    maximum_sum += run_sum[p][pos]
                    pos = dest
            if pos <= right:
                maximum_sum += nums[pos] * (right - pos + 1)
            return maximum_sum - (prefix[right + 1] - prefix[left])

        answer = 0
        for left in range(n):
            # Valid endpoints form a prefix because required increments never decrease.
            low, high = left - 1, n - 1
            while low < high:
                mid = (low + high + 1) // 2
                if increments_needed(left, mid) <= k:
                    low = mid
                else:
                    high = mid - 1
            answer += low - left + 1
        return answer

