            for i in range(n):
                mid=prev[i]
                if mid<n:
                    jj[i]=prev[mid]
                    ss[i]=ps[i]+ps[mid]
            jump.append(jj); sums.append(ss)
        pref=[0]
        for x in nums: pref.append(pref[-1]+x)
