import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [(data[i], data[i + 1]) for i in range(2, len(data), 2)]

    # For any pair i, j, f_i(f_j(x)) - f_j(f_i(x))
    # is (A_i - 1)B_j - (A_j - 1)B_i, independent of x.
    # Thus an optimal composition orders functions by (A-1)/B,
    # with larger ratios farther outside. Process from inner to outer.
    funcs.sort(key=lambda f: (f[0] - 1) / f[1])

    dp = [None] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for chosen in range(k, 0, -1):
            if dp[chosen - 1] is not None:
                value = a * dp[chosen - 1] + b
                if dp[chosen] is None or value > dp[chosen]:
                    dp[chosen] = value
    print(dp[k])

if __name__ == '__main__':
    main()

