    dp[0] = 1
    for a, b in funcs:
        for chosen in range(k, 0, -1):
            if dp[chosen - 1] is not None:
                value = a * dp[chosen - 1] + b
                if dp[chosen] is None or value > dp[chosen]:
                    dp[chosen] = value
    print(dp[k])

