from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(word):
            if not word:
                return list(range(n + 1))

            pi = [0] * len(word)
            j = 0
            for i in range(1, len(word)):
                while j and word[i] != word[j]:
                    j = pi[j - 1]
                if word[i] == word[j]:
                    j += 1
                pi[i] = j

            ans = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = pi[j - 1]
                if ch == word[j]:
                    j += 1
                if j == len(word):
                    ans.append(i - len(word) + 1)
                    j = pi[j - 1]
            return ans

        oa = occurrences(a)
        ob = occurrences(b)
        oc = occurrences(c)
        ends_a = [x + len(a) for x in oa]
        best = n + 1

        for mid in ob:
            mid_end = mid + len(b)
            if a:
                k = bisect_right(ends_a, mid) - 1
                if k < 0:
                    continue
                left = oa[k]
            else:
                left = mid

            if c:
                k = bisect_left(oc, mid_end)
                if k == len(oc):
                    continue
                right = oc[k] + len(c)
            else:
                right = mid_end

            best = min(best, right - left)

        return best if best <= n else -1

