import sys

def solve():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    pos = 1
    answers = []

    for _ in range(t):
        n = int(data[pos])
        a = data[pos + 1].decode()
        b = data[pos + 2].decode()
        pos += 3

        starts = [i for i, c in enumerate(a) if c == '1']
        targets = [i for i, c in enumerate(b) if c == '1']

        if len(starts) < len(targets):
            answers.append('-1')
            continue

        # A valid final configuration groups consecutive initial pieces at
        # each occupied target. Minimize the maximum distance in such a grouping.
        lo, hi = 0, n
        while lo < hi:
            limit = (lo + hi) // 2
            reachable = {0}
            for target in targets:
                nxt = set()
                for begin in reachable:
                    end = begin
                    while end < len(starts) and abs(starts[end] - target) <= limit:
                        end += 1
                        nxt.add(end)
                reachable = nxt
                if not reachable:
                    break
            if len(starts) in reachable:
                hi = limit
            else:
                lo = limit + 1

        answers.append(str(lo))

    sys.stdout.write('\n'.join(answers))

if __name__ == '__main__':
    solve()

