from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Construct the postorder traversal iteratively.
        order = []
        stack = [(0, 0)]
        while stack:
            v, state = stack.pop()
            if state == 0:
                stack.append((v, 1))
                for u in reversed(children[v]):
                    stack.append((u, 0))
            else:
                order.append(v)

        # Every subtree occupies a contiguous interval ending at its own node.
        pos = [0] * n
        for i, v in enumerate(order):
            pos[v] = i
        size = [1] * n
        for v in order:
            if parent[v] != -1:
                size[parent[v]] += size[v]

        text = ''.join(s[v] for v in order)

        # Manacher radii for odd-length and even-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for v in range(n):
            r = pos[v]
            l = r - size[v] + 1
            length = size[v]
            if length & 1:
                middle = (l + r) // 2
                answer[v] = odd[middle] >= length // 2 + 1
            else:
                middle = (l + r + 1) // 2
                answer[v] = even[middle] >= length // 2
