class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        # Bit s is set when sum s is achievable for this index.
        reachable = [1] * n  # Initially, only sum 0 is achievable.

        if all(x == 0 for x in nums):
            return 0

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                reachable[i] |= reachable[i] << value

            if all((reachable[i] >> nums[i]) & 1 for i in range(n)):
                return k

        return -1

