import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        def is_prime(x):
            if x < 2:
                return False
            d = 2
            while d * d <= x:
                if x % d == 0:
                    return False
                d += 1
            return True

        if is_prime(n) or is_prime(m):
            return -1

        inf = 10**30
        dist = {n: n}  # The starting value is included in the total cost.
        heap = [(n, n)]

        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist.get(x):
                continue
            if x == m:
                return cost

            digits = list(str(x))
            for i, ch in enumerate(digits):
                digit = ord(ch) - ord('0')
                for new_digit in (digit - 1, digit + 1):
                    if new_digit < 0 or new_digit > 9:
                        continue
                    # Keep the number at its original digit length.
                    if i == 0 and new_digit == 0:
                        continue
                    digits[i] = str(new_digit)
                    nxt = int(''.join(digits))
                    if not is_prime(nxt):
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, inf):
                            dist[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
                digits[i] = ch

        return -1

