from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # z[i] is the LCP length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        first_condition = [False] * n
        for i in range(1, n):
            first_condition[i] = z[i] >= i

        answer = 0
        # Let i be the length of nums1 and d the length of nums2.
        # For each fixed d, compute LCP(nums[i:], nums[i+d:]) backwards.
        for d in range(1, n):
            matched = 0
            for i in range(n - d - 1, 0, -1):
                first_works = d >= i and first_condition[i]
                if first_works:
                    answer += 1

                if nums[i] == nums[i + d]:
                    matched += 1
                else:
                    matched = 0
                if matched >= d and not first_works:
                    answer += 1

        return answer

