class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set('aeiou')
        n = len(word)
        answer = 0

        for left in range(n):
            seen_vowels = set()
            consonants = 0
            for right in range(left, n):
                char = word[right]
                if char in vowels:
                    seen_vowels.add(char)
                else:
                    consonants += 1
                    if consonants > k:
                        break

                if consonants == k and len(seen_vowels) == 5:
                    answer += 1

        return answer

